// === Tab: mySketch ===
//Background:
//Yggdrasil is the tree of life in Norse mythology!
//This sketch depicts the roots of ygrasil growing to the music, over viking runes!
//Sketch is a double fork of https://openprocessing.org/sketch/1022198 and https://openprocessing.org/sketch/2123461
//Hope you all Enjoy!

//music by Music by <a href="https://pixabay.com/users/grand_project-19033897/?utm_source=link-attribution&utm_medium=referral&utm_campaign=music&utm_content=128378">Grand_Project</a> from <a href="https://pixabay.com/music//?utm_source=link-attribution&utm_medium=referral&utm_campaign=music&utm_content=128378">Pixabay</a>

let numRunesX = 8;
let numRunesY = 2;
let runeResX = 4;
let runeResY = 7;
let sparcity = 0.15;
let linelength;  //number of nodes it can stretch to.
let symmetryInt, cSymmetryInt;
let PARTS = []
let count = 2
let start=0
let counter=0
let newtree=false
let runes = [];
let gap, thisSym, runeWidth, runeHeight;
var seed;

function preload() {
soundFormats('mp3', "wav");//load music
  song = loadSound('https://openprocessing.org/sketch/2125803/files/epicMusic.mp3');
}

function w(n) {
  if(n==null) return width
  return width*n
}

function h(n) {
  if(n==null) return height
  return height*n
}

function hsbShift(col, h, s, b){
    return color(hue(col)+h, saturation(col)+s, brightness(col)+b)
}

function randNeg(n) {
  return (n==null)?(random() < 0.5 ? 1:-1):(random() < 0.5 ? n:-n)
}

function ease(n) {
  return n**3
}

class particle {
  constructor(sx, sy, sc, ss, sd, sl, ls, tag, others) {
    this.tag = tag
    this.pos = createVector(sx, sy)
    this.col = 0
    this.siz = random(.6)
    this.asiz = ss
    this.dir = sd
    this.spd = (this.tag=="trunk")?2:random(0.25, 2)
    this.life = 500
    this.lifespan = 50000
    this.others = others
    this.thshift = random(-1, 1)*0
    this.tsshift = random(1)*0
    this.tbshift = random(-1)*0
    this.rsiz = this.asiz*this.siz
  }

  kill() {
    let index = this.others.indexOf(this)
    if(index > -1) {
      this.others.splice(index, 1)
    }
  }

  update() {
	if(counter%450==0) {
		background(random(255))

		seed = "pears";
		linelength = createVector(2,3);
		//noLoop();
		noFill();
		stroke(255);

		//calculate spacing
		runeWidth = (1.5 * windowWidth)/((numRunesX) + (numRunesX + 1));
		runeHeight = (2*windowHeight)/((2*numRunesY) + (numRunesY + 1));
		gap = runeWidth/4;	
		GenerateRunes(seed);
		this.life=50000
		this.pos= createVector(5000,5000)
	}
	else
	{
    this.rsiz = this.asiz*this.siz
    this.pos.add(createVector(cos(radians(this.dir))*this.spd, sin(radians(this.dir))*this.spd))
    this.dir += random(-1, 1)*(this.tag == "trunk" && this.siz > 0.7 ? 1:map(this.life, 0, this.lifespan, 1, 5))
    if(random() < (this.tag=="branch" ? 0.003:0.005) && this.tag!="trunk") this.dir += randNeg(72)*0
    //this.siz = smoothstep(this.siz, 0, 0.05)
    this.siz = lerp(this.siz, 0, random(0.015))
    //this.siz -= random(0.01)
    if(this.rsiz < 0.1 || this.spd > this.rsiz) {
      this.kill()
    }

    this.col = 255

    if(random() < 0.03 && this.tag=="trunk" && this.siz < .55) {
      this.others.push(new particle(this.pos.x, this.pos.y, this.col, this.rsiz, this.dir+randNeg(random(15, 30)), this.life, this.lifespan, "branch", this.others))
    }

    if(random() < 0.01 && this.tag=="branch") {
      this.others.push(new particle(this.pos.x, this.pos.y, this.col, this.rsiz, this.dir, this.life, this.lifespan, "branch", this.others))
    }

    if(random() < map(this.siz, 0, 0.25, 0.5, 0.3) && this.tag=="branch" && this.siz < 0.25) {
      this.others.push(new particle(this.pos.x, this.pos.y, this.col, (this.siz**0.5)*this.rsiz, this.dir+randNeg(random(5, 20)), 0, random(this.lifespan*0.05), "twig", this.others))
    }

    noStroke()
    fill(this.col)
    circle(this.pos.x, this.pos.y, this.siz*this.asiz)

    if(this.life > this.lifespan) {
      this.kill()
    }

    this.life++
  	}
	}
}

function setup() {
	pixelDensity(.5)
	song.play()//Source: Shiffman //plays music at start
  amp = new p5.Amplitude();//Source: Shiffman
	song.loop() //loop music

  createCanvas(1400, 800);
  //colorMode(HSB)
  background(0)

	seed = "pears";
	linelength = createVector(2,3);
	//noLoop();
	noFill();
	stroke(255);

	//calculate spacing
	runeWidth = (1.5 * windowWidth)/((numRunesX) + (numRunesX + 1));
  runeHeight = (2*windowHeight)/((2*numRunesY) + (numRunesY + 1));
	gap = runeWidth/4;	
	GenerateRunes(seed);
  noStroke()
  fill(0)
  for(let i = 0; i < count; i++) {
    PARTS.push(new particle(w(random(1)), h(1), "#000", 100, 270, 0, 900, "trunk", PARTS))
  }
}

function draw() {
	counter++
	var vol = amp.getLevel();//Source: Shiffman
  volumeLevel = round(map(vol, 0, 0.3,    4, 60));//Source: Shiffman - As the volume changes, this variable "volumeLevel" will change as well
	frameRate(volumeLevel)

	for(var p of PARTS) {
    for(let i = start; i < 2; i++) p.update()
  }
	if(counter%50==0) newtree=false

	if( newtree==false)	{
  	for(let i = 0; i < count; i++) {
    PARTS.push(new particle(w(random(1)), h(1), 0, 100, 270, 0, 900, "trunk", PARTS))
  }
		newtree=true
	}	
}


function smoothstep(start, end, amount) {
  // Clamp the value of 'amount' between 0 and 1
  amount = Math.max(0, Math.min(1, amount));

  // Calculate the interpolated value using the smoothstep equation
  return (amount * amount * (3 - 2 * amount)) * (end - start) + start;
}

function GenerateRunes(inseed) {
    InitRunes(runes);
		DrawRunes();

}

function DrawRunes() {
	//cycle through runes in array and call rune 'etch' function
	strokeWeight(max([runeResX, runeResY])/4);
	stroke(200);
	background(0);
	if(runes.length>0){
		for(let i = 0; i < runes.length; i++){
			runes[i].Etch();
		}
	}
}

function InitRunes(runes){
	//calculate spacing
	runeWidth = (windowWidth)/((1.2 * numRunesX));
  runeHeight = (windowHeight)/(1.2 * (numRunesY) );
	gap = runeWidth/4;
	//create 2d array of runes to cycle through
	runes.length = 0;
	for(let i = 0; i <numRunesX; i++){
		for(let j = 0; j < numRunesY; j++){
			let thisRuneX = ((width/numRunesX)) * i+1 + gap;
			let thisRuneY = ((height/numRunesY)) * j+1 + gap;
			let tempsym = (random(1)>0.5) ? true : false;
			runes.push(new rune(thisRuneX, thisRuneY, runeResX, runeResY, runeWidth, runeHeight, sparcity, tempsym, 0));
		}
	}
}

class rune {
	constructor(_x, _y, _resX, _resY, _rWidth, _rHeight, _sparcity, _symmetry, _type){
		this.position = createVector(_x,_y);
		this.resolution = createVector(_resX, _resY);
		this.dims = createVector(_rWidth, _rHeight);
		this.sparcity = _sparcity;
		this.symmetry = _symmetry;
		this.type = _type;
		this.nodes = []; //node coordinates here
		this.nodeDrawList = []; // index of nodes to draw here
		let nodeSeperationX = this.dims.x / this.resolution.x;
		let nodeSeperationY = this.dims.y / this.resolution.y;
		//let nodeSeperationY = nodeSeperationX;
		let drawChance;
		//store node positions in 2d array
		for(let i = 0; i < this.resolution.x; i++){
			this.nodes[i] = [];
			for(let j = 0; j < this.resolution.y; j++){
				let nodePosY = this.position.y + (nodeSeperationY * j);
				let nodePosX = this.position.x + (nodeSeperationX * i);

				this.nodes[i][j] = createVector(nodePosX, nodePosY);
				// do we use this node - not used for grid?
					this.nodeDrawList.push(i + (this.resolution.x * j)); //this converts 2d array into 1d list- not currently used but used for curved lines. 
			}
		}
	}

	Etch(){
		//this draws the rune based on its type
		if(this.type == 0){
			this.GridGlyph();
		}
	}

	GridGlyph(){

		//cycle through nodes and draw line to other node
		for(let i = 0; i < this.resolution.x; i++){
			for(let j = 0; j < this.resolution.y; j++){
				var drawChance = random(1);
				//will we draw a line?
				if(drawChance > this.sparcity){
					//choose connecting node
					let connectionY = int(random(j-linelength.y, j+linelength.y));
					let connectionX = int(random(i-linelength.x, i+linelength.x));

					//if connection out of bounds set to edge
					if(connectionY > this.resolution.y-1){
						connectionY = this.resolution.y-1;
					} else if (connectionY < 0) {
						connectionY = 0;
					}
					if(connectionX > this.resolution.x-1){
						connectionX = this.resolution.x-1;
					} else if (connectionX < 0) {
						connectionX = 0;
					}

					//symmetry
					symmetryInt = this.resolution.x - (i)-1;
					cSymmetryInt = this.resolution.x - (connectionX)-1;

					//draw lines
					strokeWeight((runeResX + runeResY)/(1.3 * ((numRunesX + numRunesY)/2)));
					stroke(200);

					line(this.nodes[i][j].x, this.nodes[i][j].y, this.nodes[connectionX][connectionY].x, this.nodes[connectionX][connectionY].y);
					if(this.symmetry == true){
						line(this.nodes[symmetryInt][j].x, this.nodes[symmetryInt][j].y, this.nodes[cSymmetryInt][connectionY].x, this.nodes[cSymmetryInt][connectionY].y);
						//print('here');
					}		
				}
			}
		}
	}
}

